6	import { describe, expect, test } from 'vitest';
7	import { Emitter } from '../../../../util/vs/base/common/event';
8	import { IAuthenticationService } from '../../../authentication/common/authentication';
9	import { TestLogService } from '../../../testing/common/testLogService';
10	import { ChatQuotaService } from '../../common/chatQuotaServiceImpl';
