51			if (
52				requestMetadata.type === RequestType.Telemetry ||
53				requestMetadata.type === RequestType.ChatCompletions ||
54				requestMetadata.type === RequestType.ChatMessages ||
55				requestMetadata.type === RequestType.ChatResponses
56			) {
57				request.callSite = NO_FETCH_TELEMETRY;
58			}
59			return super.makeRequest<T>(request, requestMetadata);
60		}
