6	import * as vscode from 'vscode';
7	import { IAuthenticationService } from '../../../platform/authentication/common/authentication';
8	import { IChatQuota, IChatQuotaService } from '../../../platform/chat/common/chatQuotaService';
9	import { Disposable } from '../../../util/vs/base/common/lifecycle';
10	
11	const QUOTA_NOTIFICATION_ID = 'copilot.quotaStatus';
12	const THRESHOLDS = [50, 75, 90, 95];
13	
14	interface IRateLimitWarning {
15		percentUsed: number;
16		type: 'session' | 'weekly';
17		resetDate: Date;
18	}
19	
20	interface IQuotaWarning {
21		percentUsed: number;
22		resetDate: Date;
23	}
24	
25	/**
26	 * Manages a single chat input notification for quota and rate limit status.
27	 *
28	 * Listens to `IChatQuotaService.onDidChange` and determines whether a
29	 * new threshold has been crossed, then shows the highest-priority notification:
30	 *
31	 * 1. **Quota exhausted** — info, not auto-dismissed, only dismissible via X.
32	 * 2. **Quota approaching** — info, auto-dismissed on next message.
33	 * 3. **Rate-limit warning** — info, auto-dismissed on next message.
34	 */
35	export class ChatInputNotificationContribution extends Disposable {
36	
37		private _notification: vscode.ChatInputNotification | undefined;
38		/** Tracks whether the current notification is the quota-exhausted variant. */
39		private _showingExhausted = false;
40		/** Whether a copilot token was present on the last {@link _update} call. */
41		private _hadCopilotToken = false;
42	
43		private readonly _shownQuotaThresholds = new Set<number>();
44		private readonly _shownSessionThresholds = new Set<number>();
45		private readonly _shownWeeklyThresholds = new Set<number>();
46	
47		constructor(
48			@IAuthenticationService private readonly _authService: IAuthenticationService,
49			@IChatQuotaService private readonly _chatQuotaService: IChatQuotaService,
50		) {
51			super();
52			this._register(this._authService.onDidAuthenticationChange(() => this._update()));
53			this._register(this._chatQuotaService.onDidChange(() => this._update()));
54		}
55	
56		/**
57		 * Single entry point that determines the highest-priority notification
58		 * to show (or whether to hide).
59		 */
60		private _update(): void {
61			const hasCopilotToken = !!this._authService.copilotToken;
62			const wasSignedIn = this._hadCopilotToken;
63			this._hadCopilotToken = hasCopilotToken;
64	
65			// Detect signed-in → signed-out transition: clear thresholds and hide.
66			if (wasSignedIn && !hasCopilotToken) {
67				this._shownQuotaThresholds.clear();
68				this._shownSessionThresholds.clear();
69				this._shownWeeklyThresholds.clear();
70				this._hideNotification();
71				this._showingExhausted = false;
72				return;
73			}
74	
75			// Skip quota notifications for PRU users — only show for UBB.
76			const isQuotaNotificationEligible = !hasCopilotToken
77				|| !!this._authService.copilotToken?.isUsageBasedBilling;
78	
79			// Priority 1: Quota exhausted — sticky info notification
80			if (isQuotaNotificationEligible && this._chatQuotaService.quotaExhausted) {
81				this._showExhaustedNotification();
82				return;
83			}
84	
85			// Priority 2: Quota approaching threshold
86			if (isQuotaNotificationEligible) {
87				const quotaWarning = this._computeQuotaWarning();
88				if (quotaWarning) {
89					this._showQuotaApproachingWarning(quotaWarning);
90					return;
91				}
92			}
93	
94			// Priority 3: Rate-limit warning (session > weekly)
95			const rateLimitWarning = this._computeRateLimitWarning();
96			if (rateLimitWarning) {
97				this._showRateLimitWarning(rateLimitWarning);
98				return;
99			}
100	
101			// Nothing new to show — only hide if the exhausted notification is
